document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".content-plenta-casa-filter").forEach(function(e){if(e.classList.contains("has-types")){var t=e.querySelector('select[name*="objectType"]'),n=e.querySelector('select[name*="[type]"]');t.addEventListener("change",function(e){n.querySelectorAll('option:not([value=""])').forEach(function(e){e.remove()}),""!==t.value&&fetch("_casa/types/"+t.value).then(function(e){return e.json()}).then(function(e){for(var t in e){var o=document.createElement("option");o.value=t,o.innerText=e[t],n.appendChild(o)}}),document.dispatchEvent(new CustomEvent("casa_typeOptionsUpdated"))})}})});